CREATE FUNCTION public.signal_filtered(_filter jsonb DEFAULT '{}') RETURNS SETOF public.signal_list_priority LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT s.* FROM signal_list_priority s WHERE coalesce((_filter->>'cancelled')::boolean,false)=(s.cancelled_at IS NOT NULL) AND (coalesce(_filter->>'q','')='' OR strpos(lower(s.customer_name),lower(btrim(_filter->>'q')))>0 OR strpos(s.phone,btrim(_filter->>'q'))>0) AND (coalesce(_filter->>'from','')='' OR CASE WHEN _filter->>'basis'='closed' THEN (s.closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date ELSE s.detected_on END>=(_filter->>'from')::date) AND (coalesce(_filter->>'to','')='' OR CASE WHEN _filter->>'basis'='closed' THEN (s.closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh')::date ELSE s.detected_on END<=(_filter->>'to')::date) AND (coalesce(_filter->>'source','')='' OR s.source=_filter->>'source') AND (coalesce(_filter->>'product','')='' OR _filter->>'product'=ANY(s.products)) AND (coalesce(_filter->>'needGroup','')='' OR _filter->>'needGroup'=ANY(CASE WHEN cardinality(s.need_groups)>0 THEN s.need_groups ELSE array_remove(ARRAY[s.need_group],NULL) END)) AND (coalesce(_filter->>'saleId','')='' OR s.assigned_to::text=_filter->>'saleId') AND (coalesce(_filter->>'creatorId','')='' OR s.created_by::text=_filter->>'creatorId') AND (NOT coalesce((_filter->>'unassigned')::boolean,false) OR s.assigned_to IS NULL) AND (coalesce(_filter->>'lostReason','')='' OR CASE WHEN s.lost_reason LIKE 'Khác%' THEN 'Khác' ELSE s.lost_reason END=_filter->>'lostReason') AND (coalesce(_filter->>'potential','')='' OR coalesce(s.potential,'unrated')=_filter->>'potential') AND (coalesce(_filter->>'labelId','')='' OR EXISTS(SELECT 1 FROM signal_label_links l WHERE l.signal_id=s.id AND l.label_id::text=_filter->>'labelId')) AND (coalesce(_filter->>'stage','')='' OR CASE WHEN s.status IS NULL OR s.status IN ('waiting','contacting') THEN 'intake' WHEN s.status IN ('consulting','quoted') THEN 'advice' WHEN s.status='lost' THEN 'ended' ELSE 'closing' END=_filter->>'stage') AND (coalesce(_filter->>'status',_filter->>'quick','all') IN ('','all') OR CASE WHEN coalesce(_filter->>'status',_filter->>'quick')='unassigned' THEN s.assigned_to IS NULL AND s.status IS NULL ELSE s.status=coalesce(_filter->>'status',_filter->>'quick') END) AND (coalesce(_filter->>'nextFrom','')='' OR s.next_contact_on>=(_filter->>'nextFrom')::date) AND (coalesce(_filter->>'nextTo','')='' OR s.next_contact_on<=(_filter->>'nextTo')::date) AND (coalesce(_filter->>'work','all')='all' OR (_filter->>'work'='high' AND s.potential='high') OR (_filter->>'work'='won' AND s.status='won') OR (_filter->>'work'='overdue' AND s.status IN ('waiting','contacting','consulting','quoted','deposit') AND s.next_contact_on<(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date) OR (_filter->>'work'='action' AND s.status IN ('waiting','contacting','consulting','quoted','deposit') AND (s.next_contact_on<=(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date OR (s.potential='high' AND s.next_contact_on IS NULL)))) $$;
REVOKE ALL ON FUNCTION signal_filtered(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION signal_filtered(jsonb) TO authenticated,service_role;
CREATE FUNCTION signal_list_page(_filter jsonb DEFAULT '{}',_sort text DEFAULT 'work',_offset integer DEFAULT 0,_limit integer DEFAULT 40) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ WITH page AS MATERIALIZED (SELECT s.*,row_number() OVER(ORDER BY CASE WHEN _sort IN ('work','priority') THEN s.list_work_priority END,CASE WHEN _sort IN ('work','priority') THEN s.list_wait_since END ASC NULLS LAST,CASE WHEN _sort='oldest' THEN s.created_at END ASC,CASE WHEN _sort='newest' THEN s.created_at END DESC,CASE WHEN _sort='soonest' THEN s.next_contact_on END ASC NULLS LAST,CASE WHEN _sort='potential' THEN CASE s.potential WHEN 'high' THEN 0 WHEN 'medium' THEN 1 WHEN 'low' THEN 2 ELSE 3 END END,CASE WHEN _sort='value' THEN s.revenue END DESC NULLS LAST,s.list_activity_at DESC,s.id) ord FROM signal_filtered(_filter) s ORDER BY ord LIMIT greatest(1,least(_limit,50)) OFFSET greatest(_offset,0)), enriched AS (SELECT p.ord,(to_jsonb(p)-'ord'-'address'-'marketing_note'-'potential_updated_by'-'potential_updated_at'-'cancel_reason')||jsonb_build_object('label_ids',coalesce((SELECT jsonb_agg(l.label_id ORDER BY l.label_id) FROM signal_label_links l WHERE l.signal_id=p.id),'[]'),'note_count',(SELECT count(*) FROM opportunity_signal_notes n WHERE n.signal_id=p.id AND signal_note_is_progression(n.note,n.event_type,n.is_progression)),'last_note',(SELECT jsonb_build_object('signal_id',n.signal_id,'created_at',n.created_at,'note',n.note,'event_type',n.event_type) FROM opportunity_signal_notes n WHERE n.signal_id=p.id AND signal_note_is_progression(n.note,n.event_type,n.is_progression) ORDER BY n.created_at DESC,n.id DESC LIMIT 1)) row FROM page p) SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(row ORDER BY ord) FROM enriched),'[]')) $$;
REVOKE ALL ON FUNCTION signal_list_page(jsonb,text,integer,integer) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION signal_list_page(jsonb,text,integer,integer) TO authenticated;
CREATE FUNCTION signal_list_counts(_filter jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ WITH base AS MATERIALIZED(SELECT * FROM signal_filtered(_filter-'quick'-'status')),needs AS MATERIALIZED(SELECT * FROM signal_filtered(_filter-'needGroup')),st AS(SELECT coalesce(status,'unassigned') key,count(*) n FROM base GROUP BY status),ng AS(SELECT g key,count(DISTINCT s.id) n FROM needs s CROSS JOIN LATERAL unnest(CASE WHEN cardinality(s.need_groups)>0 THEN s.need_groups ELSE array_remove(ARRAY[s.need_group],NULL) END) g GROUP BY g),mine AS(SELECT * FROM opportunity_signals WHERE assigned_to=auth.uid() AND cancelled_at IS NULL) SELECT jsonb_build_object('total',(SELECT count(*) FROM signal_filtered(_filter)),'status',coalesce((SELECT jsonb_object_agg(key,n) FROM st),'{}')||jsonb_build_object('all',(SELECT count(*) FROM base)),'needs',coalesce((SELECT jsonb_object_agg(key,n) FROM ng),'{}')||jsonb_build_object('all',(SELECT count(*) FROM needs)),'sales',coalesce((SELECT jsonb_agg(DISTINCT assigned_to) FILTER(WHERE assigned_to IS NOT NULL) FROM opportunity_signals),'[]'),'creators',coalesce((SELECT jsonb_agg(DISTINCT created_by) FROM opportunity_signals),'[]'),'mine',jsonb_build_object('waiting',(SELECT count(*) FROM mine WHERE status='waiting'),'active',(SELECT count(*) FROM mine WHERE status IN ('contacting','consulting','quoted','deposit')),'quoted',(SELECT count(*) FROM mine WHERE status='quoted'),'won',(SELECT count(*) FROM mine WHERE status='won' AND date_trunc('month',closed_at AT TIME ZONE 'Asia/Ho_Chi_Minh')=date_trunc('month',now() AT TIME ZONE 'Asia/Ho_Chi_Minh')))) $$;
REVOKE ALL ON FUNCTION signal_list_counts(jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION signal_list_counts(jsonb) TO authenticated;
CREATE FUNCTION signal_change_token() RETURNS text LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$SELECT md5(concat((SELECT count(*) FROM opportunity_signals),(SELECT max(updated_at) FROM opportunity_signals),(SELECT max(created_at) FROM opportunity_signal_notes),(SELECT count(*) FROM signal_label_links)))$$;
REVOKE ALL ON FUNCTION signal_change_token() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION signal_change_token() TO authenticated;